  const volWeight = tier.useVolumetricWeight ? volumetricWeightKg(input) : 0;
  const billedWeightKg = Math.max(input.actualWeightKg, volWeight);
  const freightCny = roundCurrency(row.ratePerKgCny * billedWeightKg + row.ticketFeeCny);
